<script>
  // Dynamic Pricing Synchronization Script
  (function() {
    const inputStarterMonthly = document.getElementById('inputStarterMonthly');
    const inputStarterAnnual = document.getElementById('inputStarterAnnual');
    const inputProMonthly = document.getElementById('inputProMonthly');
    const inputProAnnual = document.getElementById('inputProAnnual');
    const inputEnterpriseBase = document.getElementById('inputEnterpriseBase');

    const starterDisplays = document.querySelectorAll('.starterDisplayPrice');
    const starterCycles = document.querySelectorAll('.starterDisplayCycle');
    const proDisplays = document.querySelectorAll('.proDisplayPrice');
    const proCycles = document.querySelectorAll('.proDisplayCycle');
    const enterpriseDisplays = document.querySelectorAll('.enterpriseDisplayPrice');
    const enterpriseCycles = document.querySelectorAll('.enterpriseDisplayCycle');

    const toggleMonthly = document.getElementById('toggleMonthlyPreview');
    const toggleAnnual = document.getElementById('toggleAnnualPreview');
    let isAnnual = false;

    function updatePreview() {
      if (isAnnual) {
        starterDisplays.forEach(el => el.textContent = '₱' + (inputStarterAnnual.value || '1490'));
        starterCycles.forEach(el => el.textContent = '/year');
        proDisplays.forEach(el => el.textContent = '₱' + (inputProAnnual.value || '2990'));
        proCycles.forEach(el => el.textContent = '/year');
        enterpriseDisplays.forEach(el => el.textContent = '₱' + ((parseFloat(inputEnterpriseBase.value) * 10) || '4990'));
        enterpriseCycles.forEach(el => el.textContent = '/year');
      } else {
        starterDisplays.forEach(el => el.textContent = '₱' + (inputStarterMonthly.value || '149'));
        starterCycles.forEach(el => el.textContent = '/month');
        proDisplays.forEach(el => el.textContent = '₱' + (inputProMonthly.value || '299'));
        proCycles.forEach(el => el.textContent = '/month');
        enterpriseDisplays.forEach(el => el.textContent = '₱' + (inputEnterpriseBase.value || '499'));
        enterpriseCycles.forEach(el => el.textContent = '/month');
      }
    }

    [inputStarterMonthly, inputStarterAnnual, inputProMonthly, inputProAnnual, inputEnterpriseBase].forEach(input => {
      if (input) {
        input.addEventListener('input', updatePreview);
      }
    });

    if (toggleMonthly && toggleAnnual) {
      toggleMonthly.addEventListener('click', function() {
        isAnnual = false;
        toggleMonthly.className = "px-space-md py-1.5 rounded-lg font-label-md text-label-md font-semibold bg-surface-container-lowest text-on-surface shadow-xs transition-all";
        toggleAnnual.className = "px-space-md py-1.5 rounded-lg font-label-md text-label-md font-semibold text-on-surface-variant hover:text-on-surface transition-all flex items-center gap-1";
        updatePreview();
      });

      toggleAnnual.addEventListener('click', function() {
        isAnnual = true;
        toggleAnnual.className = "px-space-md py-1.5 rounded-lg font-label-md text-label-md font-semibold bg-surface-container-lowest text-on-surface shadow-xs transition-all flex items-center gap-1";
        toggleMonthly.className = "px-space-md py-1.5 rounded-lg font-label-md text-label-md font-semibold text-on-surface-variant hover:text-on-surface transition-all";
        updatePreview();
      });
    }

    // Trigger feedback toast on save buttons
    const toast = document.getElementById('saveToast');
    function showToast() {
      if (!toast) return;
      toast.classList.remove('translate-y-24', 'opacity-0');
      toast.classList.add('translate-y-0', 'opacity-100');
      setTimeout(() => {
        toast.classList.remove('translate-y-0', 'opacity-100');
        toast.classList.add('translate-y-24', 'opacity-0');
      }, 3200);
    }

    document.querySelectorAll('.saveTierBtn').forEach(btn => {
      btn.addEventListener('click', showToast);
    });

    const publishBtn = document.getElementById('publishChangesBtn');
    if (publishBtn) {
      publishBtn.addEventListener('click', showToast);
    }
  })();
</script></main></div>

<script>
  const superAdminNavItems = Array.from(document.querySelectorAll('[data-path]'));
  const activeNavClasses = ['bg-primary-container', 'text-on-primary-container', 'font-semibold', 'rounded-lg', 'shadow-sm'];
  const inactiveNavClasses = ['text-on-surface-variant'];
  const activePath = 'plans-pricing';

  superAdminNavItems.forEach(function (item) {
    const path = item.dataset.path;
    if (path === 'dashboard') item.href = "{{ route('super.admin') }}";
    if (path === 'businesses') item.href = "{{ route('super.admin.businesses') }}";
    if (path === 'plans-pricing') item.href = "{{ route('super.admin.plans') }}";
    if (path === 'subscriptions-billing') item.href = "{{ route('super.admin.billing') }}";
    if (path === 'platform-analytics') item.href = "{{ route('super.admin.analytics') }}";
    if (path === 'customer-activity') item.href = "{{ route('super.admin.activity') }}";
    if (path === 'support-tickets') item.href = "{{ route('super.admin.tickets') }}";
    if (path === 'platform-health') item.href = "{{ route('super.admin.health') }}";
    if (path === 'system-settings') item.href = "{{ route('super.admin.settings') }}";

    const isActive = path === activePath;
    item.classList.remove(...activeNavClasses, ...inactiveNavClasses);
    item.classList.add(...(isActive ? activeNavClasses : inactiveNavClasses));
    if (isActive) item.setAttribute('aria-current', 'page');

    item.addEventListener('click', function (event) {
      localStorage.setItem('super-admin-active-path', path);
      if (item.getAttribute('href') === '#') event.preventDefault();
      superAdminNavItems.forEach(function (navItem) {
        navItem.classList.remove(...activeNavClasses);
        navItem.classList.add(...inactiveNavClasses);
        navItem.removeAttribute('aria-current');
      });
      item.classList.remove(...inactiveNavClasses);
      item.classList.add(...activeNavClasses);
      item.setAttribute('aria-current', 'page');
    });
  });
</script>
<script src="{{ asset('js/super-admin-navigation.js') }}"></script>
</body></html>
